class Solution {
public:
    vector<int> pivotArray(vector<int>& nums, int pivot) {
        int n = nums.size();
        int lessCount = 0, equalCount = 0;
        for (int x : nums) {
            if (x < pivot) lessCount++;
            else if (x == pivot) equalCount++;
        }
        vector<int> result(n);
        int i = 0, j = lessCount, k = lessCount + equalCount;
        for (int x : nums) {
            if (x < pivot) result[i++] = x;
            else if (x == pivot) result[j++] = x;
            else result[k++] = x;
        }
        return result;
    }
};
